<?php
require_once dirname(dirname(__DIR__)).'/src/bootstrap.php';$user=Auth::requireRole('donor');
$stmt=db()->prepare('SELECT * FROM donor_profiles WHERE user_id=?');$stmt->execute([(int)$user['id']]);$profile=$stmt->fetch();
$inv=db()->prepare("SELECT ei.*,e.blood_group,e.district,e.created_at,e.status emergency_status,h.name hospital_name FROM emergency_invites ei JOIN emergency_requests e ON e.id=ei.emergency_id JOIN hospitals h ON h.id=e.hospital_id WHERE ei.donor_id=? ORDER BY ei.sent_at DESC LIMIT 12");$inv->execute([(int)$user['id']]);$invites=$inv->fetchAll();
$appt=db()->prepare("SELECT c.title,c.event_date,c.location,cr.appointment_time,cr.status,cr.attendance_status FROM campaign_registrations cr JOIN donation_campaigns c ON c.id=cr.campaign_id WHERE cr.donor_id=? AND cr.status='booked' AND c.event_date>=CURDATE() ORDER BY c.event_date,cr.appointment_time LIMIT 3");$appt->execute([(int)$user['id']]);$appointments=$appt->fetchAll();
$pageTitle='Donor Dashboard';require dirname(dirname(__DIR__)).'/src/templates/header.php';?>
<section class="dashboard"><div class="container"><div class="dash-head"><div><div class="eyebrow">Donor workspace</div><h1>Welcome, <?=e($user['full_name'])?></h1><p class="page-note">Keep your availability and consent current so hospitals only contact you when appropriate.</p></div><a class="btn" href="<?=e(url('donor/card.php'))?>">Open QR Card</a></div><?=donor_nav()?><div class="metrics"><div class="metric"><span>Blood group</span><strong><?=e($profile['blood_group'])?></strong></div><div class="metric"><span>District</span><strong style="font-size:1.25rem"><?=e($profile['district'])?></strong></div><div class="metric"><span>Availability</span><strong style="font-size:1.2rem"><?=e(ucfirst($profile['availability']))?></strong></div><div class="metric"><span>Consent</span><strong style="font-size:1.2rem"><?=e(ucfirst($profile['consent_status']))?></strong></div></div><?php if($profile['eligibility_status']!=='eligible'):?><div class="danger-note"><strong>Eligibility pending:</strong> your account is verified, but emergency matching begins only after your eligibility status is marked eligible by an authorized administrator process.</div><?php endif;?><?php if($profile['consent_status']!=='granted'):?><div class="info-note"><strong>Matching paused:</strong> your donor consent is withdrawn. You can restore it from Profile when you are ready.</div><?php endif;?><div class="grid-2 mt-2"><div><h2>Recent emergency invitations</h2><div class="table-wrap"><table class="table"><thead><tr><th>Hospital</th><th>Blood</th><th>District</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if(!$invites):?><tr><td colspan="5" class="empty">No emergency invitations yet.</td></tr><?php endif;?><?php foreach($invites as $i):?><tr><td><?=e($i['hospital_name'])?></td><td><?=e($i['blood_group'])?></td><td><?=e($i['district'])?></td><td><span class="badge <?=e($i['status']==='accepted'?'green':($i['status']==='declined'?'red':'amber'))?>"><?=e($i['status'])?></span></td><td><?php if($i['status']==='pending'&&$i['emergency_status']==='open'):?><a href="<?=e(url('donor/respond.php?id='.(int)$i['id']))?>">Respond</a><?php else:?>—<?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div><div><h2>Upcoming appointments</h2><div class="card"><?php if(!$appointments):?><p class="empty">No upcoming campaign appointments.</p><?php else:?><ul class="summary-list"><?php foreach($appointments as $a):?><li><strong><?=e($a['title'])?></strong><br><span class="small"><?=e($a['event_date'])?> · <?=e(substr($a['appointment_time'],0,5))?> · <?=e($a['location'])?></span></li><?php endforeach;?></ul><?php endif;?><p><a href="<?=e(url('donor/campaigns.php'))?>">View campaigns →</a></p></div></div></div></div></section>
<?php require dirname(dirname(__DIR__)).'/src/templates/footer.php';?>
